import * as React from "react";
import {
  PlasmicCenter,
  DefaultCenterProps
} from "./plasmic/sayban/PlasmicCenter";
import { HTMLElementRefOf } from "@plasmicapp/react-web";
import {
  CENTER_TAB_SECTIONS,
  CENTER_FAQ_TAB,
  CENTER_DAILY_LIFE_TAB,
  CENTER_AMENITIES_TAB,
  CENTER_SCROLL_OFFSET_PX,
  centerPageStyles,
  scrollToCenterSection
} from "./centerPage/index";
import { resolvePublicAuthToken } from "@/lib/publicAuthToken";
import { PUBLIC_ROUTES } from "@/lib/apiRoutes";
import { resolveCenterBannerSrc } from "./centerPage/centerBanner";
import {
  CenterFavoriteContext,
  parseNumericCenterId
} from "./favorites/CenterFavoriteContext";

/** Short TTL so revisiting a center paints instantly while still refreshing. */
const CENTER_PUBLIC_CACHE_TTL_MS = 5 * 60 * 1000;

function loadJalaaliOnce() {
  if (typeof window === "undefined") return;
  if ((window as Window & { jalaali?: unknown }).jalaali) return;
  if (document.querySelector("script[data-sayban-jalaali]")) return;
  const script = document.createElement("script");
  script.src = "https://cdn.jsdelivr.net/npm/jalaali-js/dist/jalaali.js";
  script.async = true;
  script.dataset.saybanJalaali = "1";
  document.head.appendChild(script);
}

export interface CenterProps extends DefaultCenterProps {}

export { CENTER_TAB_SECTIONS } from "./centerPage/index";

function assignRef<T>(
  ref: React.ForwardedRef<T> | undefined,
  value: T | null
) {
  if (typeof ref === "function") {
    ref(value);
  } else if (ref) {
    ref.current = value;
  }
}

function Center_(props: CenterProps, ref: HTMLElementRefOf<"div">) {
  const TABS_REVEAL_SCROLL_PX = 300;

  const [activeTab, setActiveTab] = React.useState<string>(
    CENTER_TAB_SECTIONS[0].value
  );
  const [tabSections, setTabSections] = React.useState<
    { label: string; value: string }[]
  >([...CENTER_TAB_SECTIONS]);
  const [tabsRevealed, setTabsRevealed] = React.useState(false);
  const [centerResult, setCenterResult] = React.useState<Record<string, unknown> | null>(null);

  const scrollRootRef = React.useRef<HTMLDivElement | null>(null);
  /** While a tab click smooth-scroll is in flight, ignore ScrollSpy updates. */
  const ignoreSpyUntilRef = React.useRef(0);
  const pendingSectionRef = React.useRef<string | null>(null);
  const scrollEndTimerRef = React.useRef<number>(0);
  const publicToken = resolvePublicAuthToken(props.token);

  React.useEffect(() => {
    const updateDynamicTabs = () => {
      const faqEl = document.getElementById("center-faq");
      const amenitiesEl = document.getElementById("center-amenities");
      const careEl = document.getElementById("center-care-treatment");
      const hoursEl = document.getElementById("center-care");
      const dailyLifeEl = document.getElementById("center-daily-life");
      const familyEl = document.getElementById("center-family");
      const hasFaq = Boolean(faqEl);
      const hasAmenities = Boolean(amenitiesEl);
      const hasCare = Boolean(careEl);
      const hasWorkingHours = Boolean(hoursEl);
      const hasDailyLife = Boolean(dailyLifeEl);
      const hasFamily = Boolean(familyEl);

      let sections: { label: string; value: string }[] = [
        ...CENTER_TAB_SECTIONS
      ].filter(tab => {
        if (tab.value === "center-care") return hasWorkingHours;
        return true;
      });

      if (hasDailyLife) {
        sections = [...sections, { ...CENTER_DAILY_LIFE_TAB }];
      }
      if (hasAmenities) {
        sections = [...sections, { ...CENTER_AMENITIES_TAB }];
      }
      if (hasFaq) {
        sections = [...sections, { ...CENTER_FAQ_TAB }];
      }

      void hasCare;
      void hasFamily;

      setTabSections(sections);
    };
    updateDynamicTabs();
    const root = scrollRootRef.current;
    let observer: MutationObserver | null = null;
    if (root && typeof MutationObserver !== "undefined") {
      observer = new MutationObserver(() => updateDynamicTabs());
      observer.observe(root, { childList: true, subtree: true });
    }
    const t1 = window.setTimeout(updateDynamicTabs, 400);
    return () => {
      observer?.disconnect();
      window.clearTimeout(t1);
    };
  }, [centerResult]);

  React.useEffect(() => {
    const root = scrollRootRef.current;
    if (!root) return;

    const sectionIds = tabSections.map(t => t.value);

    const syncActiveFromScroll = () => {
      // Keep the clicked tab active while smooth-scroll is in progress.
      if (pendingSectionRef.current) {
        if (Date.now() < ignoreSpyUntilRef.current) return;
        pendingSectionRef.current = null;
        ignoreSpyUntilRef.current = 0;
      }

      const rootTop = root.getBoundingClientRect().top;
      let current = sectionIds[0];

      for (const id of sectionIds) {
        const el = document.getElementById(id);
        if (!el) continue;
        // Position relative to the scroll container's visible top.
        const top = el.getBoundingClientRect().top - rootTop;
        if (top - CENTER_SCROLL_OFFSET_PX <= 1) {
          current = id;
        }
      }

      if (current) {
        setActiveTab(prev => (prev === current ? prev : current));
      }
    };

    const observer = new IntersectionObserver(
      () => {
        syncActiveFromScroll();
      },
      {
        root,
        rootMargin: `-${CENTER_SCROLL_OFFSET_PX}px 0px -50% 0px`,
        threshold: [0, 0.1, 0.25, 0.5, 0.75, 1]
      }
    );

    sectionIds.forEach(id => {
      const el = document.getElementById(id);
      if (el) observer.observe(el);
    });

    let raf = 0;
    const onScroll = () => {
      const revealed = root.scrollTop >= TABS_REVEAL_SCROLL_PX;
      setTabsRevealed(prev => (prev === revealed ? prev : revealed));

      // Release click-lock shortly after smooth scroll settles.
      if (pendingSectionRef.current) {
        window.clearTimeout(scrollEndTimerRef.current);
        scrollEndTimerRef.current = window.setTimeout(() => {
          pendingSectionRef.current = null;
          ignoreSpyUntilRef.current = 0;
          syncActiveFromScroll();
        }, 140);
      }

      if (raf) return;
      raf = window.requestAnimationFrame(() => {
        raf = 0;
        syncActiveFromScroll();
      });
    };

    syncActiveFromScroll();
    setTabsRevealed(root.scrollTop >= TABS_REVEAL_SCROLL_PX);
    root.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", syncActiveFromScroll);

    return () => {
      observer.disconnect();
      root.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", syncActiveFromScroll);
      window.clearTimeout(scrollEndTimerRef.current);
      if (raf) window.cancelAnimationFrame(raf);
    };
  }, [tabSections]);

  const handleTabSelected = (val: string, meta?: { _plasmic_state_init_?: boolean }) => {
    // Plasmic writable-state init also fires onSelectedChange — don't scroll.
    if (meta?._plasmic_state_init_) {
      if (val) setActiveTab(val);
      return;
    }
    if (!val) return;

    setActiveTab(val);
    pendingSectionRef.current = val;
    // Fallback unlock if scroll events never fire (already at position, etc.).
    ignoreSpyUntilRef.current = Date.now() + 1600;
    scrollToCenterSection(val, { container: scrollRootRef.current });
  };

  const favoriteCenterId =
    parseNumericCenterId(centerResult?.id) || parseNumericCenterId(props.id);

  return (
    <CenterFavoriteContext.Provider
      value={{ centerId: favoriteCenterId, token: publicToken }}
    >
    <PlasmicCenter
      {...props}
      token={publicToken}
      entryOpendialog={props.entryOpendialog}
      onEntryOpendialogChange={(value: boolean) => {
        if (value) loadJalaaliOnce();
        props.onEntryOpendialogChange?.(value);
      }}
      root={{
        ref: (node: HTMLDivElement | null) => {
          scrollRootRef.current = node;
          assignRef(ref, node);
        },
        className: [
          centerPageStyles.pageRoot,
          tabsRevealed && centerPageStyles.pageRootTabsRevealed,
          props.className
        ]
          .filter(Boolean)
          .join(" "),
        wrapChildren: (children: React.ReactNode) =>
          React.Children.map(children, child => {
            if (!React.isValidElement(child)) return child;
            const code = (child.props as { code?: unknown })?.code;
            if (typeof code === "string" && code.includes("jalaali")) {
              return null;
            }
            return child;
          })
      }}
      overrides={{
        topics: {
          props: {
            data: tabSections,
            selected: activeTab,
            size: "small" as const,
            onSelectedChange: handleTabSelected
          }
        },
        // Nested under the visit/time dialog — must not push its own history
        // entry or the parent visit dialog closes with it on dismiss.
        selectuser: {
          props: {
            disableModalHash: true
          }
        },
        // Review sheet: no open autofocus — mobile keyboard must only open on tap.
        comment: {
          props: {
            disableOpenAutoFocus: true
          }
        },
        commentArea: {
          props: {
            autoFocus: false
          }
        },
        // Public preview: unauthenticated n8n webhook, keyed by MD5 center id.
        full: {
          render: (renderProps: any, DefaultApiRequest: any) => (
            <DefaultApiRequest
              {...renderProps}
              url={PUBLIC_ROUTES.centerPublic}
              config={undefined}
              params={{ id: props.id ?? "" }}
              cacheKey={
                props.id ? `public-center:${String(props.id)}` : undefined
              }
              cacheTtlMs={CENTER_PUBLIC_CACHE_TTL_MS}
              onSuccess={(data: any) => {
                setCenterResult(data?.result ?? null);
                renderProps.onSuccess?.(data);
              }}
            />
          )
        },
        swiperSlider: {
          render: (renderProps: any, DefaultSwiper: any) => (
            <DefaultSwiper {...renderProps}>
              {React.Children.map(renderProps.children, child =>
                React.isValidElement(child)
                  ? React.cloneElement(child as React.ReactElement<any>, {
                      src: resolveCenterBannerSrc(centerResult)
                    })
                  : child
              )}
            </DefaultSwiper>
          )
        }
      }}
    />
    </CenterFavoriteContext.Provider>
  );
}

const Center = React.forwardRef(Center_);
export default Center;
